INSERT INTO oms.operations VALUES (262, '20', 'Facing & Centering', '00:45:00', '00:08:00', NULL, 16, NULL, 'Face both ends of the bar stock to achieve parallel surfaces. Center drill both ends to support subsequent turning operations.', 'Ensure face runout <0.01mm. Center drill depth = 3mm.', '2026-03-18 17:55:55.022102+05:30', '2026-03-18 17:55:55.022102+05:30', 1, NULL, NULL, 16, NULL);
INSERT INTO oms.operations VALUES (263, '30', 'Rough Turning (OD)', '01:00:00', '00:12:00', NULL, 16, NULL, 'Rough turn the outer diameter leaving 0.5mm stock for finish pass. Follow the turning profile as per drawing. Coolant on at all times.', 'Cutting speed: 180 m/min. Feed: 0.25 mm/rev. Depth of cut: 2mm.', '2026-03-18 17:55:55.022102+05:30', '2026-03-18 17:55:55.022102+05:30', 1, NULL, NULL, 16, NULL);
INSERT INTO oms.operations VALUES (264, '40', 'Finish Turning (OD)', '00:30:00', '00:10:00', NULL, 16, NULL, 'Finish turn OD to final dimension per drawing. Achieve surface finish Ra 1.6 um. Check diameter at 3 locations along length.', 'Use sharp insert. Cutting speed: 220 m/min. Feed: 0.10 mm/rev.', '2026-03-18 17:55:55.022102+05:30', '2026-03-18 17:55:55.022102+05:30', 1, NULL, NULL, 16, NULL);
INSERT INTO oms.operations VALUES (265, '50', 'Drilling (Center Bore)', '00:45:00', '00:06:00', NULL, 16, NULL, 'Drill center bore to specified diameter and depth as per drawing. Ensure bore is concentric with OD within 0.02mm TIR.', 'Peck drilling recommended for depths >3x diameter. Use cutting oil.', '2026-03-18 17:55:55.022102+05:30', '2026-03-18 17:55:55.022102+05:30', 1, NULL, NULL, 16, NULL);
