INSERT INTO oms.operations VALUES (267, '70', 'Thread Cutting (External)', '00:45:00', '00:07:00', NULL, 16, NULL, 'Cut external thread per drawing specification. Verify thread form using Go/No-Go gauge. Deburr thread after cutting.', 'Thread spec: M20x1.5-6g. First article must be approved before batch run.', '2026-03-18 17:55:55.022102+05:30', '2026-03-18 17:55:55.022102+05:30', 1, NULL, NULL, 16, NULL);
INSERT INTO oms.operations VALUES (268, '80', 'Milling (Keyway)', '01:00:00', '00:11:00', NULL, 16, NULL, 'Mill keyway slot to drawing dimensions. Ensure keyway is parallel to bore axis within 0.02mm per 100mm. Deburr all edges post-milling.', 'End mill: 8mm dia, 4-flute HSS. Feed: 150 mm/min. Depth of cut: 1mm per pass.', '2026-03-18 17:55:55.022102+05:30', '2026-03-18 17:55:55.022102+05:30', 1, NULL, NULL, 16, NULL);
INSERT INTO oms.operations VALUES (269, '90', 'Deburring & Chamfering', '00:20:00', '00:05:00', NULL, 16, NULL, 'Remove all sharp edges and burrs from all machined surfaces. Apply chamfers as specified on drawing. Use hand files and deburring tools.', 'Chamfer 0.5x45 deg unless otherwise specified. Inspect all surfaces visually.', '2026-03-18 17:55:55.022102+05:30', '2026-03-18 17:55:55.022102+05:30', 1, NULL, NULL, 16, NULL);
